CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE IF NOT EXISTS catalog_config (id boolean PRIMARY KEY DEFAULT true CHECK (id), client_name text NOT NULL, whatsapp_number text NOT NULL, active_design text NOT NULL DEFAULT 'editorial', revision bigint NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, sort_order integer NOT NULL DEFAULT 0, visible boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source text NOT NULL DEFAULT 'manual', source_id text, source_url text, name text NOT NULL, sku text, price numeric(12,2) NOT NULL DEFAULT 0, compare_at_price numeric(12,2), currency char(3) NOT NULL DEFAULT 'INR', description text NOT NULL DEFAULT '', category_id uuid REFERENCES categories(id), stock integer NOT NULL DEFAULT 0, metadata jsonb NOT NULL DEFAULT '{}', source_fingerprint text, source_updated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source, source_id));
CREATE TABLE IF NOT EXISTS product_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, url text NOT NULL, alt_text text, position integer NOT NULL DEFAULT 0, width integer, height integer, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_variants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, source_id text, title text NOT NULL, sku text, price numeric(12,2), stock integer, options jsonb NOT NULL DEFAULT '{}', UNIQUE(product_id, source_id));
CREATE TABLE IF NOT EXISTS sync_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source text NOT NULL, status text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, created_count integer NOT NULL DEFAULT 0, updated_count integer NOT NULL DEFAULT 0, unchanged_count integer NOT NULL DEFAULT 0, error_count integer NOT NULL DEFAULT 0, summary jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS sync_errors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sync_run_id uuid NOT NULL REFERENCES sync_runs(id) ON DELETE CASCADE, source_product_id text, stage text NOT NULL, message text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS products_category_idx ON products(category_id);
CREATE INDEX IF NOT EXISTS products_source_idx ON products(source, source_id);
CREATE INDEX IF NOT EXISTS products_updated_idx ON products(updated_at DESC);
CREATE INDEX IF NOT EXISTS products_search_idx ON products USING gin (to_tsvector('simple', coalesce(name,'') || ' ' || coalesce(sku,'') || ' ' || coalesce(description,'')));
